<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Administración | Adbana</title><link rel="icon" type="image/svg+xml" href="/images/adbana-logo.svg"><link rel="stylesheet" href="/css/panel.css?v=20261106-toast"><link rel="stylesheet" href="/css/administracion.css?v=20261031"><script src="/js/administracion.js?v=20261106c"></script><script defer src="/js/alpine.min.js"></script><link rel="stylesheet" href="/css/carga.css?v=20261031d"></head>
<body><div class="app-root platform-root" x-data="administracion" x-cloak @keydown.tab.window="atraparFoco($event)" @keydown.escape.window="if(!busy){editor=null;eliminando=null;menu=false}">
@include('layouts.carga', ['visible' => 'consultasBackend > 0 && (busy || cargando)', 'bloqueante' => 'busy'])

<template x-if="admin"><div :inert="!!editor||!!eliminando"><div class="sidebar-backdrop" x-show="menu" @click="menu=false"></div><aside class="sidebar" :class="{'is-open':menu}" aria-label="Administración"><div class="restaurant-brand"><img class="brand-logo" src="/images/adbana-logo.svg" width="30" height="40" alt=""><strong>ADBANA</strong><button class="mobile-only icon-button" @click="menu=false" aria-label="Cerrar menú"><svg class="icon"><use href="/images/panel-icons.svg#close"></use></svg></button></div><div class="workspace-caption">CONTROL DE LA PLATAFORMA</div><nav class="nav"><template x-for="n in navegacion" :key="n.id"><button :class="{active:seccion===n.id}" :aria-current="seccion===n.id?'page':null" :disabled="busy" @click="ir(n.id)"><span class="nav-icon"><svg class="icon" aria-hidden="true"><use :href="'/images/panel-icons.svg#'+n.icono"></use></svg></span><span x-text="n.nombre"></span></button></template></nav><div class="sidebar-bottom"><span class="platform-scope">Administración general</span><small>Accesos y operación de Adbana</small></div></aside>
<div class="workspace"><header class="platform-topbar"><div class="row"><button class="icon-button mobile-only" @click="menu=true" aria-label="Abrir menú"><svg class="icon"><use href="/images/panel-icons.svg#menu"></use></svg></button><span class="muted">Plataforma <span class="platform-slash">/</span> <strong x-text="titulo"></strong></span></div><div class="row"><div class="platform-person"><strong x-text="admin.name"></strong><small x-text="admin.rol==='superadmin'?'Superadministrador':'Administrador'"></small></div><span class="platform-avatar" x-text="iniciales"></span><button class="icon-button" @click="salir()" :disabled="busy" aria-label="Cerrar sesión"><svg class="icon"><use href="/images/panel-icons.svg#logout"></use></svg></button></div></header>
<main class="platform-main"><div class="platform-heading"><div><span class="eyebrow">ADBANA · PANEL GENERAL</span><h1 x-text="titulo"></h1><p class="muted" x-text="seccion==='resumen'?'Una mirada a los negocios y la actividad de tu plataforma.':seccion==='restaurantes'?'Consulta los negocios registrados y su estado de acceso.':seccion==='administradores'?'Cada persona, con su propia cuenta y los permisos necesarios.':seccion==='perfil'?'Tu información y seguridad de acceso.':'Un registro de las decisiones y los cambios de acceso.'"></p></div><div class="row"><select x-show="seccion==='resumen'" aria-label="Periodo del dashboard" x-model="dias" @change="cargar()" :disabled="busy||cargando"><option value="7">Últimos 7 días</option><option value="30">Últimos 30 días</option></select><button class="icon-button" @click="cargar()" :disabled="busy||cargando" aria-label="Actualizar"><svg class="icon"><use href="/images/panel-icons.svg#refresh"></use></svg></button><button class="primary" x-show="seccion==='administradores'" @click="editar()" :disabled="busy">Añadir administrador</button></div></div>
<p class="alert" role="alert" x-show="error&&!editor&&!eliminando" x-text="error"></p>@include('layouts.aviso')<section class="card" x-show="credencial" role="status"><h2>Credenciales iniciales</h2><p>La contraseña se muestra solo en esta pantalla. Compártela por un canal seguro; la persona podrá cambiarla en Mi perfil.</p><p x-text="credencial?.email"></p><label>Contraseña generada<input :type="verCredencial?'text':'password'" :value="credencial?.password||''" readonly autocomplete="off"></label><button type="button" @click="verCredencial=!verCredencial" x-text="verCredencial?'Ocultar':'Mostrar contraseña'"></button><button type="button" @click="credencial=null;verCredencial=false">Ya la guardé</button></section><p class="muted" role="status" x-show="cargando">Actualizando información…</p>
<section x-show="seccion==='perfil'" class="card"><h2>Mi perfil</h2><p class="muted">Tu correo y permisos los gestiona un superadministrador. Puedes cambiar tu nombre y contraseña.</p><p x-text="admin.email"></p><form @submit.prevent="guardarPerfil()"><label>Nombre<input x-model="perfil.name" required maxlength="120" autocomplete="name"></label><label>Contraseña actual<input type="password" x-model="perfil.password_actual" required autocomplete="current-password"></label><label>Nueva contraseña (opcional)<input type="password" x-model="perfil.password" minlength="12" maxlength="72" autocomplete="new-password"></label><label>Repite la nueva contraseña<input type="password" x-model="perfil.password_confirmation" :required="!!perfil.password" autocomplete="new-password"></label><button class="primary" :disabled="busy">Guardar mi perfil</button></form></section>
<section x-show="seccion==='resumen'&&resumen"><div class="platform-kpis">
<article class="card platform-kpi"><span class="platform-kpi-icon red"><svg class="icon"><use href="/images/panel-icons.svg#food"></use></svg></span><span>Restaurantes activos</span><strong x-text="numero(resumen?.restaurantes_activos)"></strong><small x-text="numero(resumen?.restaurantes_total)+' registrados en total'"></small></article>
<article class="card platform-kpi"><span class="platform-kpi-icon blue"><svg class="icon"><use href="/images/panel-icons.svg#chart"></use></svg></span><span>Con actividad en 7 días</span><strong x-text="numero(resumen?.restaurantes_con_pedidos_7dias)"></strong><small>Negocios que registraron pedidos</small></article>
<article class="card platform-kpi"><span class="platform-kpi-icon amber"><svg class="icon"><use href="/images/panel-icons.svg#bag"></use></svg></span><span>Nuevos restaurantes</span><strong x-text="numero(resumen?.altas_periodo)"></strong><small x-text="'En los últimos '+dias+' días'"></small></article>
<article class="card platform-kpi"><span class="platform-kpi-icon purple"><svg class="icon"><use href="/images/panel-icons.svg#users"></use></svg></span><span>Administradores activos</span><strong x-text="numero(resumen?.administradores_activos)"></strong><small>Equipo de la plataforma</small></article></div>
<div class="platform-chart-grid"><article class="card"><div class="platform-card-title"><div><h2>Actividad de la plataforma</h2><p class="muted">Pedidos registrados en el periodo</p></div><strong class="platform-big" x-text="numero(resumen?.pedidos_periodo)"></strong></div><svg class="platform-chart" viewBox="0 0 700 190" role="img" aria-label="Pedidos por día"><path d="M20 30H680 M20 75H680 M20 120H680 M20 160H680" stroke="var(--line)" fill="none"/><polygon :points="'20,160 '+grafico('pedidos')+' 680,160'" fill="#ef483914"/><polyline :points="grafico('pedidos')" fill="none" stroke="#ef4839" stroke-width="3" stroke-linejoin="round"/></svg><div class="platform-chart-labels"><span x-text="serie[0]?.fecha"></span><span x-text="serie[serie.length-1]?.fecha"></span></div><details class="platform-chart-data"><summary>Consultar valores por día</summary><div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Pedidos</th><th>Altas</th></tr></thead><tbody><template x-for="d in serie" :key="d.fecha"><tr><td x-text="d.fecha"></td><td x-text="numero(d.pedidos)"></td><td x-text="numero(d.restaurantes)"></td></tr></template></tbody></table></div></details></article>
<article class="card"><h2>Crecimiento de restaurantes</h2><p class="muted">Nuevos negocios registrados por día</p><strong class="platform-big" x-text="numero(resumen?.altas_periodo)"></strong><svg class="platform-chart" viewBox="0 0 700 190" role="img" aria-label="Altas de restaurantes por día"><path d="M20 30H680 M20 75H680 M20 120H680 M20 160H680" stroke="var(--line)" fill="none"/><polyline :points="grafico('restaurantes')" fill="none" stroke="#4d80e4" stroke-width="3" stroke-linejoin="round"/></svg><div class="platform-chart-labels"><span x-text="serie[0]?.fecha"></span><span x-text="serie[serie.length-1]?.fecha"></span></div></article></div>
<div class="platform-chart-grid"><article class="card"><h2>Necesitan atención</h2><div class="platform-attention"><span class="platform-dot amber"></span><div><strong x-text="numero(resumen?.sin_pedidos_7dias)+' negocios sin pedidos recientes'"></strong><p class="muted">Restaurantes activos sin pedidos registrados durante los últimos 7 días.</p></div><button x-show="admin.permisos_efectivos.restaurantes" @click="ir('restaurantes')">Revisar</button></div><div class="platform-attention"><span class="platform-dot grey"></span><div><strong>Suscripciones y vencimientos</strong><p class="muted">Sin configurar. Se mostrarán cuando se active la gestión de planes.</p></div></div><div class="platform-attention"><span class="platform-dot grey"></span><div><strong>Incidencias de soporte</strong><p class="muted">Sin configurar. No hay un módulo de tickets conectado.</p></div></div></article><article class="card"><h2>Últimos restaurantes</h2><p class="muted" x-show="!resumen?.recientes.length">Todavía no hay restaurantes registrados.</p><template x-for="r in resumen?.recientes||[]" :key="r.id"><div class="platform-recent"><span class="platform-initial" x-text="r.nombre.slice(0,1).toUpperCase()"></span><div><strong x-text="r.nombre"></strong><small x-text="fecha(r.created_at)"></small></div><span class="platform-badge" :class="r.activo?'ok':'off'" x-text="r.activo?'Activo':'Suspendido'"></span></div></template></article></div><p class="muted platform-updated" x-text="'Datos del entorno actual · Actualizado '+fecha(resumen?.actualizado_at)"></p></section>
<section x-show="seccion!=='resumen'&&seccion!=='perfil'&&seccion"><form class="platform-filters" @submit.prevent="buscar()" x-show="seccion!=='auditoria'"><div class="platform-search"><svg class="icon"><use href="/images/panel-icons.svg#search"></use></svg><input x-model="busqueda" maxlength="120" :placeholder="seccion==='restaurantes'?'Buscar restaurante…':'Buscar nombre o correo…'" aria-label="Buscar"></div><select x-model="estado" x-show="seccion==='restaurantes'" aria-label="Estado"><option value="">Todos los estados</option><option value="1">Activos</option><option value="0">Suspendidos</option></select><button :disabled="busy||cargando">Buscar</button></form>
<div class="card platform-table-card"><div class="table-scroll"><table class="platform-table"><thead><tr x-show="seccion==='restaurantes'"><th>Restaurante</th><th>Estado</th><th>Equipo</th><th>Último pedido</th><th>Acciones</th></tr><tr x-show="seccion==='administradores'"><th>Persona</th><th>Rol</th><th>Estado</th><th>Último acceso</th><th>Acciones</th></tr><tr x-show="seccion==='auditoria'"><th>Fecha</th><th>Persona</th><th>Acción</th><th>Recurso</th><th>Motivo</th></tr></thead><tbody><template x-for="r in filas" :key="seccion+'-'+r.id"><tr>
<template x-if="seccion==='restaurantes'"><td><strong x-text="r.nombre"></strong><small x-text="'/c/'+r.slug"></small></td></template><template x-if="seccion==='restaurantes'"><td><span class="platform-badge" :class="r.activo?'ok':'off'" x-text="r.activo?'Activo':'Suspendido'"></span></td></template><template x-if="seccion==='restaurantes'"><td x-text="r.usuarios+' personas'"></td></template><template x-if="seccion==='restaurantes'"><td x-text="fecha(r.ultimo_pedido_at)"></td></template><template x-if="seccion==='restaurantes'"><td><button x-show="admin.permisos_efectivos.gestionar_restaurantes" @click="cambiarRestaurante(r)" :disabled="busy" x-text="r.activo?'Suspender':'Activar'"></button><button class="platform-danger" x-show="admin.permisos_efectivos.eliminar_restaurantes" @click="eliminarRestaurante(r)" :disabled="busy">Eliminar</button><span class="muted" x-show="!admin.permisos_efectivos.gestionar_restaurantes&&!admin.permisos_efectivos.eliminar_restaurantes">Solo consulta</span></td></template>
<template x-if="seccion==='administradores'"><td><strong x-text="r.name"></strong><small x-text="r.email"></small></td></template><template x-if="seccion==='administradores'"><td x-text="r.rol==='superadmin'?'Superadministrador':'Administrador'"></td></template><template x-if="seccion==='administradores'"><td><span class="platform-badge" :class="r.activo?'ok':'off'" x-text="r.activo?'Activo':'Inactivo'"></span></td></template><template x-if="seccion==='administradores'"><td x-text="fecha(r.ultimo_acceso_at)"></td></template><template x-if="seccion==='administradores'"><td><div class="row" x-show="r.id!==admin.id"><button @click="editar(r)" :disabled="busy">Editar</button><button class="platform-danger" @click="prepararEliminacion(r)" :disabled="busy">Eliminar</button></div><span class="muted" x-show="r.id===admin.id">Tu cuenta</span></td></template>
<template x-if="seccion==='auditoria'"><td x-text="fecha(r.created_at)"></td></template><template x-if="seccion==='auditoria'"><td x-text="r.actor"></td></template><template x-if="seccion==='auditoria'"><td x-text="accion(r.accion)"></td></template><template x-if="seccion==='auditoria'"><td x-text="r.recurso+' #'+(r.recurso_id||'—')"></td></template><template x-if="seccion==='auditoria'"><td x-text="r.motivo||'—'"></td></template>
</tr></template></tbody></table></div><div class="platform-empty" x-show="!filas.length&&!cargando"><svg class="icon"><use href="/images/panel-icons.svg#search"></use></svg><h3>No hay resultados</h3><p class="muted">Prueba otra búsqueda o añade el primer registro.</p></div><nav class="platform-pagination" aria-label="Paginación"><span x-text="numero(total)+' registros'"></span><div class="row"><button @click="cambiarPagina(pagina-1)" :disabled="busy||cargando||pagina<=1">Anterior</button><span x-text="pagina+' / '+ultima"></span><button @click="cambiarPagina(pagina+1)" :disabled="busy||cargando||pagina>=ultima">Siguiente</button></div></nav></div></section>
<p class="muted" x-show="!seccion">Tu cuenta no tiene secciones habilitadas. Solicita al superadministrador que revise tus permisos.</p>
</main></div></div></template>
<div class="modal" x-ref="editorDialog" x-show="editor" role="dialog" aria-modal="true" aria-labelledby="editor-titulo"><form class="card dialog platform-dialog" @submit.prevent="guardarAdmin()"><h2 id="editor-titulo" x-text="editor?.id?'Editar administrador':'Añadir administrador'"></h2><template x-if="editor"><div><div class="platform-form-grid"><label>Nombre<input x-model="editor.name" required maxlength="120" autocomplete="off"></label><label>Correo<input type="email" x-model="editor.email" required maxlength="255" autocomplete="off"></label><label>Rol<select x-model="editor.rol"><option value="administrador">Administrador con permisos</option><option value="superadmin">Superadministrador · control total</option></select></label><label>Estado<select x-model.number="editor.activo"><option :value="1">Activo</option><option :value="0">Inactivo</option></select></label></div><fieldset class="platform-permissions" x-show="editor.rol==='administrador'"><legend>Funciones autorizadas</legend><template x-for="(titulo,clave) in catalogo" :key="clave"><label><input type="checkbox" x-model="editor.permisos[clave]"><span x-text="titulo"></span></label></template><small class="muted">Solo un superadministrador puede gestionar otros administradores.</small></fieldset><p class="platform-warning" x-show="editor.rol==='superadmin'">Esta persona tendrá control total sobre la administración de Adbana.</p><label x-show="!editor.id"><input type="checkbox" x-model="editor.generar_password">Generar contraseña inicial aleatoria</label><div class="platform-form-grid" x-show="editor.id||!editor.generar_password"><label><span x-text="editor.id?'Contraseña nueva (opcional)':'Contraseña inicial'"></span><input type="password" x-model="editor.password" :required="!editor.id&&!editor.generar_password" minlength="12" maxlength="72" autocomplete="new-password"></label><label>Repite la contraseña<input type="password" x-model="editor.password_confirmation" :required="!!editor.password&&(!editor.generar_password||!!editor.id)" autocomplete="new-password"></label></div><label>Motivo del cambio<textarea x-model="motivo" required minlength="5" maxlength="500" placeholder="Ej. Incorporación al equipo de soporte"></textarea></label><label><span x-text="admin?.confirmacion_con_pin?'Confirma con tu PIN':'Confirma tu contraseña'"></span><input type="password" x-model="passwordActual" required :inputmode="admin?.confirmacion_con_pin?'numeric':'text'" :pattern="admin?.confirmacion_con_pin?'[0-9]{9}':null" :minlength="admin?.confirmacion_con_pin?9:null" :maxlength="admin?.confirmacion_con_pin?9:null" :autocomplete="admin?.confirmacion_con_pin?'off':'current-password'"></label></div></template><p class="alert" role="alert" x-show="error" x-text="error"></p><div class="row"><button type="button" @click="editor=null;passwordActual=''" :disabled="busy">Cancelar</button><button class="primary" :disabled="busy" x-text="busy?'Guardando…':'Guardar administrador'"></button></div></form></div>
<div class="modal" x-ref="confirmacionDialog" x-show="eliminando" role="dialog" aria-modal="true" aria-labelledby="confirmacion-titulo"><form class="card dialog platform-dialog" @submit.prevent="eliminando?.restaurante?confirmarRestaurante():eliminar()"><h2 id="confirmacion-titulo" x-text="eliminando?.restaurante?(eliminando.borrar?'Eliminar restaurante del servicio':eliminando.activo?'Suspender restaurante':'Activar restaurante'):'Eliminar administrador'"></h2><p x-text="eliminando?.restaurante?eliminando.nombre:eliminando?.name"></p><p class="muted" x-text="eliminando?.restaurante?(eliminando.borrar?'Se retirarán los accesos, la carta y los pedidos públicos. No se borran ventas, caja ni auditoría. Esta acción no es un borrado definitivo de los datos.':'El cambio afecta al acceso operativo del restaurante y queda registrado.'):'Se retirará el acceso de esta persona. Su historial de auditoría se conserva.'"></p><label x-show="eliminando?.borrar">Escribe el nombre exacto del restaurante<input x-model="nombreConfirmacion" :required="!!eliminando?.borrar" maxlength="120" autocomplete="off"></label><label>Motivo<textarea x-model="motivo" required minlength="5" maxlength="500"></textarea></label><label><span x-text="admin?.confirmacion_con_pin?'Confirma con tu PIN':'Confirma tu contraseña'"></span><input type="password" required x-model="passwordActual" :inputmode="admin?.confirmacion_con_pin?'numeric':'text'" :pattern="admin?.confirmacion_con_pin?'[0-9]{9}':null" :minlength="admin?.confirmacion_con_pin?9:null" :maxlength="admin?.confirmacion_con_pin?9:null" :autocomplete="admin?.confirmacion_con_pin?'off':'current-password'"></label><p class="alert" role="alert" x-show="error" x-text="error"></p><div class="row"><button type="button" @click="eliminando=null;passwordActual=''" :disabled="busy">Cancelar</button><button class="primary" :disabled="busy" x-text="busy?'Procesando…':'Confirmar'"></button></div></form></div>
</div></body></html>
